        },
      });
    }
    return json({
      records: [
        {
          uri: `at://${did}/site.standard.document/${documentRkey}`,
          value: {
            $type: "site.standard.document",
            site: publicationUri,
            path: `/${documentRkey}`,
            title: "A Piece",
            publishedAt: "2026-08-03T12:00:00.000Z",
          },
        },
