      try {
        assertUsageEvent(row.event);
        return (
          row.eventKey === row.event.eventKey &&
          row.occurredAt === row.event.occurredAt
        );
      } catch {
        return false;
      }
    });
    const last = rows.at(-1);
    return {
      rows: valid,
      cursor:
        rows.length === boundedLimit(input.limit) && last
          ? encodeUsageCursor({
