const HANDLE_MAX = 30;
const HANDLE_RE = /^[a-z0-9](?:[a-z0-9]|-(?=[a-z0-9])){1,28}[a-z0-9]$/;

/**
 * Top-level route segments reserved by the app. A writer can't claim any of
