function download(content: string, filename: string, mime: string): void {
  const href = URL.createObjectURL(new Blob([content], { type: mime }));
  const link = document.createElement("a");
  link.href = href;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(href);
}

export const DataControls = component$<{
  range: UsageRange;
  rowCount: number;
  accountId?: string;
  onLocalDeleted$: QRL<() => void>;
  onSynchronizedDelete$?: QRL<() => Promise<void>>;
}>(props => {
  const message = useSignal("");
  const readiness = useSignal<UsageSyncReadiness>({ status: "disabled" });
  const confirmLocal = useSignal(false);
  const confirmRemote = useSignal(false);

  const exportHistory = $(async (format: "json" | "csv") => {
    const content = await usageLedger.exportUsageHistory({ from: props.range.from, to: props.range.to, format });
    download(content, `twyne-usage-${new Date().toISOString().slice(0, 10)}.${format}`, format === "json" ? "application/json" : "text/csv");
    await captureProductEvent("usage_exported", { format, row_count_bucket: usageExportRowCountBucket(props.rowCount) });
    message.value = `Downloaded ${props.rowCount.toLocaleString()} content-free usage rows.`;
  });
  const toggleSync = $(async () => {
    if (!props.accountId) return;
    const current = await usageSyncReadiness(props.accountId);
    readiness.value = current.status === "ready" ? await setUsageSyncEnabled({ accountId: props.accountId, enabled: false }) : await setUsageSyncEnabled({ accountId: props.accountId, enabled: true });
    if (readiness.value.status === "ready") window.dispatchEvent(new Event(USAGE_SYNC_REQUEST_EVENT));
  });
  const resolveSwitch = $(async (choice: "attach-unsynchronized" | "keep-device-only") => {
    if (!props.accountId) return;
    await resolveUsageAccountSwitch({ accountId: props.accountId, choice });
    readiness.value = await usageSyncReadiness(props.accountId);
    window.dispatchEvent(new Event(USAGE_SYNC_REQUEST_EVENT));
  });
  const deleteLocal = $(async () => {
    await usageLedger.deleteUsageHistory({ includeWritingActivity: true });
    await captureProductEvent("usage_history_deleted", { scope: "local" });
    confirmLocal.value = false;
    message.value = "Local usage and writing-activity history was removed from this browser.";
    props.onLocalDeleted$();
  });
  const deleteSynchronized = $(async () => {
    if (!props.onSynchronizedDelete$) return;
    await props.onSynchronizedDelete$();
    await captureProductEvent("usage_history_deleted", { scope: "synchronized" });
    confirmRemote.value = false;
    message.value = "Synchronized usage history was removed from the signed-in account.";
  });

  return (
    <section aria-labelledby="data-controls-heading" class="border-t-2 border-[var(--color-ink)] py-7">
      <p class="dept-label">05 / Custody</p>
      <h2 id="data-controls-heading" class="mt-1 font-display text-2xl">Your data controls</h2>
      <p class="mt-2 max-w-2xl text-sm text-[var(--color-ink-muted)]">Exports contain usage metadata only. They structurally exclude manuscripts, prompts, responses, provider keys, and tokens.</p>
      <div class="mt-5 grid gap-5 lg:grid-cols-3">
        <div class="border-t border-[var(--color-ink)] pt-3"><h3 class="font-display text-lg">Export this range</h3><div class="mt-3 flex gap-2"><button type="button" class="btn-paper" onClick$={() => exportHistory("json")}>JSON</button><button type="button" class="btn-paper" onClick$={() => exportHistory("csv")}>CSV</button></div></div>
        <div class="border-t border-[var(--color-ink)] pt-3"><h3 class="font-display text-lg">Combine devices</h3>{props.accountId ? <><button type="button" class="btn-paper mt-3" onClick$={toggleSync}>{readiness.value.status === "ready" ? "Stop usage sync" : "Enable usage sync"}</button>{readiness.value.status === "account_choice_required" && <div class="mt-3 text-sm"><p>This browser was associated with another account. Choose how unsynchronized rows should be handled.</p><div class="mt-2 flex flex-wrap gap-2"><button class="btn-paper" type="button" onClick$={() => resolveSwitch("attach-unsynchronized")}>Attach to this account</button><button class="btn-paper" type="button" onClick$={() => resolveSwitch("keep-device-only")}>Keep device-only</button></div></div>}</> : <p class="mt-3 text-sm text-[var(--color-ink-muted)]">Sign in to explicitly combine content-free usage across devices.</p>}</div>
        <div class="border-t border-[var(--color-ink)] pt-3"><h3 class="font-display text-lg">Delete history</h3><div class="mt-3 flex flex-wrap gap-2"><button type="button" class="btn-paper" onClick$={() => { confirmLocal.value = true; }}>This device</button><button type="button" class="btn-paper" disabled={!props.onSynchronizedDelete$} onClick$={() => { confirmRemote.value = true; }}>Synchronized</button></div>{!props.onSynchronizedDelete$ && props.accountId && <p class="mt-2 text-xs text-[var(--color-ink-muted)]">Synchronized deletion is unavailable until the account endpoint is ready.</p>}</div>
      </div>
      {confirmLocal.value && <div role="alertdialog" aria-label="Confirm local usage deletion" class="mt-5 border border-[var(--color-vermilion)] p-4 text-sm"><p>Delete local usage and writing-activity history from this browser? This cannot be undone.</p><div class="mt-3 flex gap-2"><button type="button" class="btn-press" onClick$={deleteLocal}>Delete local history</button><button type="button" class="btn-paper" onClick$={() => { confirmLocal.value = false; }}>Cancel</button></div></div>}
      {confirmRemote.value && <div role="alertdialog" aria-label="Confirm synchronized usage deletion" class="mt-5 border border-[var(--color-vermilion)] p-4 text-sm"><p>Delete synchronized usage history from this account? Local browser rows remain unless you remove them separately.</p><div class="mt-3 flex gap-2"><button type="button" class="btn-press" onClick$={deleteSynchronized}>Delete synchronized history</button><button type="button" class="btn-paper" onClick$={() => { confirmRemote.value = false; }}>Cancel</button></div></div>}
      {message.value && <p class="mt-4 text-sm" role="status">{message.value}</p>}
    </section>
  );
