  "90d": "Last 90 UTC days",
  all: "All recorded usage",
};

interface DeskStore {
  summary: UsageSummary;
  titles: Record<string, string>;
  folioCount: number;
  eventCount: number;
  loaded: boolean;
  detailsTruncated: boolean;
  remoteState: "idle" | "loading" | "ready" | "offline" | "error";
