}

async function listLocalEvents(from: number | null, to: number): Promise<UsageEvent[]> {
  const events: UsageEvent[] = [];
  let cursor: string | undefined;
  do {
    const page = await usageLedger.listUsageEvents({ from, to, cursor });
    events.push(...page.events);
    cursor = page.cursor;
  } while (cursor);
  return events;
}

export default component$(() => {
  const now = Date.now();
  const auth = useAuth();
  const clientSignal = useConvexClient();
  const preset = useSignal<UsageRangePreset>("30d");
  const revision = useSignal(0);
  const initialRange = createUsageRange("30d", now);
  const store = useStore<DeskStore>({
    summary: buildUsageSummary({ events: [], activities: [], range: initialRange, now }),
    titles: {},
    folioCount: 0,
    eventCount: 0,
    loaded: false,
    detailsTruncated: false,
    remoteState: "idle",
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ track }) => {
    const selectedPreset = track(() => preset.value);
    track(() => revision.value);
    store.loaded = false;
    const loadedAt = Date.now();
    const range = createUsageRange(selectedPreset, loadedAt);
    const [events, folios, activities] = await Promise.all([
      listLocalEvents(range.from, range.to),
      loadFoliosFromIdb(),
      usageLedger.listWritingActivity({ from: range.from ?? 0, to: range.to, limit: 2_000 }),
    ]);
    const folioMetadata: FolioUsageMetadata[] = await Promise.all(folios.map(async folio => ({
      folioId: folio.id,
      currentWords: countDraftWords(await loadFolioContentFromIdb(folio.id)),
      updatedAt: folio.updatedAt,
    })));
    store.titles = Object.fromEntries(folios.map(folio => [folio.id, folio.name]));
    store.folioCount = folios.length;
    store.eventCount = events.length;
    store.detailsTruncated = activities.length === 2_000;
    store.summary = buildUsageSummary({ events, activities, folios: folioMetadata, range, now: loadedAt });
    store.loaded = true;
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ track }) => {
    const client = track(() => clientSignal.value);
    const provider = track(() => auth.value.provider);
    const user = track(() => auth.value.user);
    const loading = track(() => auth.value.loading);
    const selectedPreset = track(() => preset.value);
    if (loading || provider !== "convex" || !user || !client) {
      store.remoteState = typeof navigator !== "undefined" && !navigator.onLine ? "offline" : "idle";
      store.synchronized = undefined;
      return;
    }
    if (!navigator.onLine) {
      store.remoteState = "offline";
      return;
    }
    store.remoteState = "loading";
    const queriedAt = Date.now();
    const requested = createUsageRange(selectedPreset, queriedAt);
    const recent = selectedPreset === "all" ? createUsageRange("90d", queriedAt) : requested;
    try {
      const [coverage] = await Promise.all([
        client.query(api.usage.getMyCoverage, {}),
        client.query(api.usage.getMySummary, { from: requested.from, to: requested.to, now: queriedAt }),
        client.query(api.usage.getMyDaily, { from: recent.from!, to: recent.to }),
        client.query(api.writingActivity.getMyActivity, { from: recent.from!, to: recent.to }),
      ]);
      store.synchronized = coverage as SynchronizedCoverage;
      store.remoteState = "ready";
    } catch {
      store.remoteState = navigator.onLine ? "error" : "offline";
    }
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(() => {
    void captureProductEvent("desk_viewed", { signed_in: Boolean(auth.value.user), range: preset.value });
  });

  const selectRange = $((range: UsageRangePreset) => {
    preset.value = range;
    history.replaceState(history.state, "", `/desk/?range=${range}`);
    void captureProductEvent("usage_range_changed", { range });
  });
  const reloadLocal = $(() => { revision.value += 1; });
  const deleteSynchronized = $(async () => {
    const client = clientSignal.value;
    if (!client || auth.value.provider !== "convex") throw new Error("Synchronized deletion requires a signed-in account");
    await client.mutation(api.usage.deleteMyUsageHistory, {});
    store.synchronized = undefined;
  });

  const dailyCutoff = createUsageRange("90d", store.summary.range.to - 1).from!;
  const displaySummary: UsageSummary = preset.value === "all"
    ? { ...store.summary, daily: store.summary.daily.filter(point => Date.parse(`${point.day}T00:00:00.000Z`) >= dailyCutoff) }
    : store.summary;
  const sourceState = !store.loaded ? "loading" : store.detailsTruncated || store.remoteState === "error" ? "partial" : store.remoteState === "offline" ? "offline" : "local";
  const accountId = auth.value.provider === "convex" ? auth.value.user?.analyticsId : undefined;

  return (
    <main class="min-h-screen bg-[var(--color-paper)] px-4 py-8 text-[var(--color-ink)] sm:px-8">
      <div class="mx-auto max-w-6xl">
        <DeskSummary displayName={auth.value.user?.name ?? auth.value.atproto?.displayName ?? "Writer on this device"} signedIn={auth.value.provider === "convex"} rangeLabel={RANGE_LABELS[preset.value]} writingDays={store.summary.writingHeatmap.filter(day => day.count > 0).length} folioCount={store.folioCount} metrics={store.summary.overall} sourceState={sourceState} synchronized={store.synchronized} />
        <nav class="flex flex-wrap items-center gap-2 border-b border-dotted border-[var(--color-ink-muted)] py-4" aria-label="Usage range">
          <span class="mr-2 text-xs font-semibold tracking-[0.1em] uppercase text-[var(--color-ink-muted)]">Range</span>
          {(["7d", "30d", "90d", "all"] as UsageRangePreset[]).map(range => <button key={range} type="button" aria-pressed={preset.value === range} class={{ "btn-paper": true, "bg-[var(--color-ink)] text-[var(--color-paper)]": preset.value === range }} onClick$={() => selectRange(range)}>{range === "all" ? "All" : range.slice(0, -1)}</button>)}
        </nav>
        {!store.loaded ? <div class="py-20" role="status"><p class="dept-label">Reading the ledger</p><div class="mt-4 h-px w-full animate-pulse bg-[var(--color-ink-muted)]" /></div> : (
          <>
            <WritingActivity days={store.summary.writingHeatmap} daily={displaySummary.daily} folioTitles={store.titles} truncated={store.detailsTruncated} />
            <UsageCost summary={displaySummary} totalsOnly={preset.value === "all"} />
            <WriterPatterns patterns={store.summary.patterns} folioTitles={store.titles} />
            <RecentWork entries={store.summary.recentWork} folioTitles={store.titles} />
            <DataControls range={store.summary.range} rowCount={store.eventCount} accountId={accountId} onLocalDeleted$={reloadLocal} onSynchronizedDelete$={accountId && clientSignal.value ? deleteSynchronized : undefined} />
          </>
        )}
      </div>
    </main>
  );
});

