interface EventPage {
  events: UsageEvent[];
  truncated: boolean;
}

async function listLocalEvents(range: UsageRange): Promise<EventPage> {
  const events: UsageEvent[] = [];
  let cursor: string | undefined;
  let pages = 0;
  do {
    const page = await usageLedger.listUsageEvents({ from: range.from, to: range.to, cursor });
    events.push(...page.events);
    cursor = page.cursor;
    pages += 1;
  } while (cursor && pages < MAX_LOCAL_PAGES);
  return { events, truncated: Boolean(cursor) };
}

async function listPendingEvents(accountId: string, range: UsageRange): Promise<EventPage> {
  const events: UsageEvent[] = [];
  let cursor: string | undefined;
  let pages = 0;
  do {
    const page = await usageLedger.listPendingUsageEvents({ accountId, cursor, limit: 100 });
    events.push(...page.events.filter(event => event.occurredAt < range.to && (range.from === null || event.occurredAt >= range.from)));
    cursor = page.cursor;
    pages += 1;
  } while (cursor && pages < MAX_LOCAL_PAGES);
  return { events, truncated: Boolean(cursor) };
}

async function folioMetadata() {
  const folios = await loadFoliosFromIdb();
  const metadata: FolioUsageMetadata[] = await Promise.all(folios.map(async folio => ({
    folioId: folio.id,
    currentWords: countDraftWords(await loadFolioContentFromIdb(folio.id)),
    updatedAt: folio.updatedAt,
  })));
  return { folios, metadata };
}

